// Generated by build.tcl. Every candidate ball is readable and drivable over JTAG.
module pinfinder (
    inout  wire [82:0] io,
    input  wire [2:0] ci
);
    wire [165:0] src;  // src[i] = output enable, src[83+i] = output value

    genvar i;
    generate
        for (i = 0; i < 83; i = i + 1) begin : drv
            assign io[i] = src[i] ? src[83+i] : 1'bz;
        end
    endgenerate

    altsource_probe #(
        .sld_auto_instance_index("YES"),
        .sld_instance_index(0),
        .instance_id("PF"),
        .probe_width(86),
        .source_width(166),
        .source_initial_value("0"),
        .enable_metastability("NO")
    ) issp (
        .probe({ci, io}),
        .source(src)
    );
endmodule
